fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based index, so the element to remove is at position k-1 in 0-based indexing.
    // According to problem, 1 <= k < n, so k-1 is valid and not the last element.
    let remove_idx = k - 1;
    let n = list.len();

    // Create a new vector with capacity n-1 for efficiency.
    let mut new_list = Vec::with_capacity(n - 1);

    // Extend with elements before remove_idx.
    new_list.extend_from_slice(&list[0..remove_idx]);
    // Extend with elements after remove_idx.
    new_list.extend_from_slice(&list[remove_idx+1..n]);

    new_list
}